/**
 * Distribui o gabarito entre A e E (a posição da correta segue a ordem 0,1,2,3,4,...),
 * girando as alternativas. Evita que "chutar sempre a mesma letra" funcione.
 */
/** Ordem da prova de Analista-Tributário 2023: Prova 1 (manhã) e Prova 2 (tarde). Economia e Auditoria (Auditor) ficam só no modo Estudar. */
const ORDEM_RFB = [
  "Língua Portuguesa", "Língua Inglesa", "Raciocínio Lógico e Estatística", "Contabilidade", "Administração Geral e Pública", "Fluência de Dados",
  "Direito Constitucional", "Direito Administrativo", "Direito Tributário e Previdenciário", "Legislação Tributária", "Legislação Aduaneira",
  "Economia", "Auditoria",
];
const MATERIAS_SIMULADO_RFB = ORDEM_RFB.slice(0, 11);
export const QUESTOES_RFB: QuestaoME[] = [...QUESTOES_RFB_BASE]
  .sort((a, b) => ORDEM_RFB.indexOf(a.materia) - ORDEM_RFB.indexOf(b.materia))
  .map((q, i) => {
  const alvo = ((i * 3) % 5) as QuestaoME["correta"];
  const desloc = (alvo - q.correta + 5) % 5;
  const alternativas = q.alternativas.map((_, idx) => q.alternativas[(idx - desloc + 5) % 5]) as QuestaoME["alternativas"];
  return { ...q, alternativas, correta: alvo };
});

/** Simulado completo da Receita: as 140 questões na estrutura da prova de Analista-Tributário (70 + 70). */
export const QUESTOES_RFB_SIMULADO: QuestaoME[] = QUESTOES_RFB.filter((q) => MATERIAS_SIMULADO_RFB.includes(q.materia));

